import { el } from './dom';

/** 轻提示。整屏只保留一条，后出现的替换先出现的。 */

let current: { node: HTMLElement; timer: number } | null = null;

function container(): HTMLElement | null {
  const host = document.getElementById('yueji-guanjia-host');
  return host?.shadowRoot ? (host.shadowRoot.querySelector('.yj-layer') as HTMLElement | null) : null;
}

export function toast(message: string, duration_ms = 1800): void {
  const layer = container();
  if (!layer) return;
  if (current) {
    window.clearTimeout(current.timer);
    current.node.remove();
    current = null;
  }
  const node = el('div', { class: 'yj-toast', text: message });
  layer.append(node);
  const timer = window.setTimeout(() => {
    node.remove();
    current = null;
  }, duration_ms);
  current = { node, timer };
}