import type { TavernContext } from '../tavern/env';
import { clear, el, on } from './dom';
import { icon } from './icons';

/** 主面板外壳。顶部栏负责标题与齿轮，底部标签在两个一级页之间切换。 */

export type PanelPageName = 'instructions' | 'characters' | 'settings';

export interface PanelHandle {
  root: HTMLElement;
  backdrop: HTMLElement;
  open: (page?: PanelPageName) => void;
  close: () => void;
  is_open: () => boolean;
  destroy: () => void;
}

export interface PanelHooks {
  /** 面板显示或隐藏时通知外部。浮动工具条靠这个让位，避免压在面板按钮上面。 */
  on_visibility?: (visible: boolean) => void;
}

function empty_state(name: 'bookmark' | 'user', text: string): HTMLElement {
  return el('div', { class: 'yj-empty' }, [
    el('div', { class: 'yj-empty__mark', html: icon(name, 30) }),
    el('div', { class: 'yj-empty__text', text }),
  ]);
}

function section(title: string, hint: string, body: HTMLElement): HTMLElement {
  return el('div', { class: 'yj-section' }, [
    el('div', { class: 'yj-section__head' }, [
      el('div', { class: 'yj-section__title', text: title }),
      hint ? el('div', { class: 'yj-section__hint', text: hint }) : '',
    ]),
    body,
  ]);
}

export function create_panel(context: TavernContext | null, hooks: PanelHooks = {}): PanelHandle {
  const title_node = el('div', { class: 'yj-panel__title', text: '角色' });
  const subtitle_node = el('div', { class: 'yj-panel__subtitle' });
  const back_button = el('button', {
    class: 'yj-iconbtn yj-panel__back',
    html: icon('back', 19),
    title: '返回',
    attrs: { type: 'button', 'aria-label': '返回' },
  });
  const gear_button = el('button', {
    class: 'yj-iconbtn yj-panel__gear',
    html: icon('gear', 19),
    title: '设置',
    attrs: { type: 'button', 'aria-label': '设置' },
  });
  const close_button = el('button', {
    class: 'yj-iconbtn yj-panel__close',
    html: icon('close', 19),
    title: '关闭',
    attrs: { type: 'button', 'aria-label': '关闭' },
  });

  const body = el('div', { class: 'yj-panel__body' });

  const tab_instructions = el('button', {
    class: 'yj-tab',
    attrs: { type: 'button', 'data-page': 'instructions' },
  });
  tab_instructions.append(el('span', { html: icon('folder', 19) }), el('span', { text: '番外指令' }));

  const tab_characters = el('button', {
    class: 'yj-tab',
    attrs: { type: 'button', 'data-page': 'characters' },
  });
  tab_characters.append(el('span', { html: icon('user', 19) }), el('span', { text: '角色' }));

  const tabs = el('div', { class: 'yj-panel__tabs' }, [tab_instructions, tab_characters]);

  const bar = el('div', { class: 'yj-panel__bar' }, [
    back_button,
    title_node,
    subtitle_node,
    el('div', { class: 'yj-panel__actions' }, [gear_button, close_button]),
  ]);

  const root = el('div', { class: 'yj-panel' }, [bar, body, tabs]);
  const backdrop = el('div', { class: 'yj-backdrop' });

  let page: PanelPageName = 'characters';

  function current_character_name(): string {
    const characters = context?.characters ?? [];
    const index = Number(context?.characterId);
    if (!Number.isFinite(index)) return '';
    return characters[index]?.name ?? '';
  }

  function page_instructions(): HTMLElement {
    return el('div', { class: 'yj-page' }, [
      section(
        '番外指令',
        '全局收藏，不分角色',
        empty_state('bookmark', '还没有收藏的番外指令。搜索、文件夹与一键复制会在后续单元接入。'),
      ),
    ]);
  }

  function page_characters(): HTMLElement {
    const characters = context?.characters ?? [];
    const index = Number(context?.characterId);
    const rows: HTMLElement[] = [];

    if (!characters.length) {
      return el('div', { class: 'yj-page' }, [
        section('角色', '', empty_state('user', '现在读不到角色卡列表，或者酒馆里还没有角色。')),
      ]);
    }

    for (const [position, character] of characters.entries()) {
      const is_current = Number.isFinite(index) && position === index;
      const row = el('div', { class: 'yj-row' }, [
        el('div', { class: 'yj-row__main' }, [
          el('div', { class: 'yj-row__title', text: character.name || '未命名角色' }),
          el('div', { class: 'yj-row__meta', text: is_current ? '当前角色' : '已启用' }),
        ]),
      ]);
      if (is_current) row.classList.add('is-current');
      rows.push(row);
    }

    return el('div', { class: 'yj-page' }, [
      section(
        '角色',
        '每个角色的收藏彼此独立',
        el('div', { class: 'yj-card' }, rows),
      ),
      el('div', { class: 'yj-note', text: '进入某个角色的截图库和文本库会在后续单元接入。' }),
    ]);
  }

  function page_settings(): HTMLElement {
    return el('div', { class: 'yj-page' }, [
      section(
        '备份',
        '图片不进备份',
        empty_state('bookmark', '导出全部文字收藏会在后续单元接入。'),
      ),
      section('关于', '', el('div', { class: 'yj-note', text: '月季管家 0.1.0  本地存储，不上传任何内容。' })),
    ]);
  }

  function render(): void {
    clear(body);
    if (page === 'instructions') body.append(page_instructions());
    else if (page === 'settings') body.append(page_settings());
    else body.append(page_characters());

    const is_settings = page === 'settings';
    back_button.style.display = is_settings ? '' : 'none';
    tabs.style.display = is_settings ? 'none' : '';
    gear_button.classList.toggle('is-active', is_settings);

    title_node.textContent = is_settings
      ? '设置'
      : page === 'instructions'
        ? '番外指令'
        : '角色';
    const name = current_character_name();
    subtitle_node.textContent = !is_settings && page === 'characters' && name ? name : '';

    tab_instructions.classList.toggle('is-active', page === 'instructions');
    tab_characters.classList.toggle('is-active', page === 'characters');
    body.scrollTop = 0;
  }

  function go(next: PanelPageName): void {
    page = next;
    render();
  }

  const disposers: Array<() => void> = [
    on<Event>(tab_instructions, 'click', () => {
      go('instructions');
    }),
    on<Event>(tab_characters, 'click', () => {
      go('characters');
    }),
    on<Event>(gear_button, 'click', () => {
      go('settings');
    }),
    on<Event>(back_button, 'click', () => {
      go('characters');
    }),
    on<Event>(close_button, 'click', () => {
      api.close();
    }),
    on<Event>(backdrop, 'click', () => {
      api.close();
    }),
  ];

  const api: PanelHandle = {
    root,
    backdrop,
    open: next => {
      if (next) page = next;
      render();
      root.style.display = '';
      backdrop.style.display = '';
      hooks.on_visibility?.(true);
    },
    close: () => {
      root.style.display = 'none';
      backdrop.style.display = 'none';
      hooks.on_visibility?.(false);
    },
    is_open: () => root.style.display !== 'none',
    destroy: () => {
      for (const dispose of disposers) dispose();
    },
  };

  root.style.display = 'none';
  backdrop.style.display = 'none';
  render();

  return api;
}