/**
 * 酒馆扩展的运行环境。
 *
 * 扩展加载在酒馆主页面（不是消息楼层 iframe），所以这里不使用 iframe 侧的 TavernHelper。
 * 只依赖酒馆明确提供给扩展的稳定接口 `SillyTavern.getContext()`
 * （见 @types/iframe/exported.sillytavern.d.ts 末尾的说明）。
 *
 * 这里只声明本项目真正用到的字段，避免把整个酒馆接口当成事实。
 */

export interface TavernContext {
  /** 当前角色卡在 characters 数组里的下标。未选中角色时为空串。 */
  characterId?: number | string;
  /** 角色卡列表。avatar 是酒馆官方注明的唯一标识，用于按角色隔离收藏。 */
  characters?: Array<{ name?: string; avatar?: string }>;
  chatId?: string;
  isMobile?: () => boolean;
  getCurrentChatId?: () => string;
  eventSource?: {
    on: (event: string, handler: (...args: never[]) => void) => void;
    removeListener?: (event: string, handler: (...args: never[]) => void) => void;
  };
  eventTypes?: Record<string, string>;
  extensionSettings?: Record<string, unknown>;
  saveSettingsDebounced?: () => void;
  uuidv4?: () => string;
}

interface TavernApi {
  getContext?: () => TavernContext;
}

function tavern_api(): TavernApi | null {
  const candidate = (globalThis as { SillyTavern?: unknown }).SillyTavern;
  if (!candidate || typeof candidate !== 'object') return null;
  return candidate as TavernApi;
}

/** 立即读取酒馆接口。不可用时返回 null，不抛错。 */
export function read_context(): TavernContext | null {
  const api = tavern_api();
  if (!api || typeof api.getContext !== 'function') return null;
  try {
    const context = api.getContext();
    return context && typeof context === 'object' ? context : null;
  } catch (error) {
    console.warn('[月季管家] 读取酒馆接口失败', error);
    return null;
  }
}

/** 等待酒馆接口出现。扩展有时会比接口更早加载，所以这里重试到超时。 */
export async function wait_context(timeout_ms = 15000): Promise<TavernContext | null> {
  const deadline = Date.now() + timeout_ms;
  for (;;) {
    const context = read_context();
    if (context) return context;
    if (Date.now() >= deadline) return null;
    await new Promise<void>(resolve => {
      setTimeout(resolve, 250);
    });
  }
}

/** 是否移动端。读不到酒馆接口时退化为屏幕宽度判断。 */
export function is_mobile(context: TavernContext | null): boolean {
  try {
    const value = context?.isMobile?.();
    if (typeof value === 'boolean') return value;
  } catch (error) {
    console.warn('[月季管家] 判断移动端失败', error);
  }
  return window.matchMedia('(max-width: 768px)').matches;
}